{"command":"cd /home/fandrieu/projets/media-workspace/newznab-tmux/database/schema && python3 - <<'EOF'
import re
s=open('mariadb-schema.sql').read()
for m in re.finditer(r'CREATE TABLE `(\w+)` \((.*?)\n\)', s, re.S):
    t,body=m.group(1),m.group(2)
    cols=re.findall(r'`(releases?_id)`',body)
    if cols:
        fk=re.findall(r'FOREIGN KEY \(`(releases?_id)`\) REFERENCES `releases`[^\n]*?(ON DELETE \w+( \w+)?)?',body)
        print(f"{t:40} {sorted(set(cols))} FK={[f[1] or 'no action' for f in fk] or 'none'}")
EOF","exitCode":0,"success":true}
